package com.medtrack.auth.entity;
import com.medtrack.shared.model.BaseEntity; import com.medtrack.user.entity.User; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="refresh_tokens") public class RefreshToken extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="token_hash",nullable=false,unique=true) private String tokenHash; @Column(name="family_id",nullable=false) private UUID familyId; @Column(name="expires_at",nullable=false) private Instant expiresAt; @Column(name="revoked_at") private Instant revokedAt; @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="replaced_by") private RefreshToken replacedBy; @Column(name="reuse_detected",nullable=false) private boolean reuseDetected; protected RefreshToken(){} public RefreshToken(User u,String hash,UUID family,Instant expires){user=u;tokenHash=hash;familyId=family;expiresAt=expires;} public User getUser(){return user;} public String getTokenHash(){return tokenHash;} public UUID getFamilyId(){return familyId;} public Instant getExpiresAt(){return expiresAt;} public Instant getRevokedAt(){return revokedAt;} public boolean isReuseDetected(){return reuseDetected;} public void revoke(Instant when){revokedAt=when;} public void markReuseDetected(){reuseDetected=true;} public void setReplacedBy(RefreshToken replacement){replacedBy=replacement;} }
